input.command:
Get-ChildItem "D:\My Drive\Blue AI\.claude\skills" -Directory | ForEach-Object {
    $skillPath = $_.FullName
    $skillMd = Join-Path $skillPath "SKILL.md"
    $hasSkillMd = Test-Path $skillMd
    $firstLine = if ($hasSkillMd) { (Get-Content $skillMd -TotalCount 5 | Where-Object { $_ -match "\S" } | Select-Object -First 1) } else { "No SKILL.md" }
    $size = (Get-ChildItem $skillPath -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum / 1KB
    [PSCustomObject]@{
        Name = $_.Name
        SizeKB = [math]::Round($size, 1)
        Summary = $firstLine
    }
} | Format-Table -AutoSize

