input.command:
Get-ChildItem "D:\My Drive\Blue AI\.claude\skills" -Directory | ForEach-Object {
    $skillMd = Join-Path $_.FullName "SKILL.md"
    if (Test-Path $skillMd) {
        $desc = (Get-Content $skillMd -Raw) -replace "(?s)^---\r?\n.*?\ndescription:\s*([^\r\n]+).*", '$1'
        [PSCustomObject]@{
            Skill = $_.Name
            Description = $desc.Substring(0, [math]::Min(120, $desc.Length))
        }
    }
} | Format-Table -Wrap

